SELECT *
FROM policy_coverage_detail
WHERE EXTRACT(YEAR FROM Effective_Date) = 2019;

SELECT Year_Built, Number_of_Firefighters
FROM fire_claim
WHERE Year_Built BETWEEN 1960 AND 1969;

SELECT Year_Built, Fireplace
FROM fire_claim
WHERE Year_Built BETWEEN 1990 AND 1999;

SELECT Nearest_Firestation_miles, Number_of_Firefighters
FROM fire_claim
WHERE Fireplace = 'No' AND Loss_Ratio >= 1;

SELECT Year_Built, Loss_Ratio
FROM fire_claim
WHERE Fireplace = 'Yes' AND Number_of_Firefighters >= 9;

SELECT Year_Built, Number_of_Firefighters
FROM fire_claim
WHERE Nearest_Firestation_miles < 2;

SELECT Fireplace, COUNT(*) AS record_count
FROM fire_claim
GROUP BY Fireplace;

SELECT Fireplace, AVG(Year_Built) AS average_year_built
FROM fire_claim
GROUP BY Fireplace;

SELECT Fireplace, AVG(Nearest_Firestation_miles) AS avg_station_distance_miles
FROM fire_claim
GROUP BY Fireplace;

SELECT Fireplace, AVG(Loss_Ratio) AS average_loss_ratio
FROM fire_claim
GROUP BY Fireplace;

SELECT Number_of_Firefighters, COUNT(*) AS record_count
FROM fire_claim
GROUP BY Number_of_Firefighters;

SELECT Number_of_Firefighters, AVG(Year_Built) AS avg_year_built
FROM fire_claim
GROUP BY Number_of_Firefighters;

SELECT Loss_Ratio, AVG(Year_Built) AS avg_year_built
FROM fire_claim
GROUP BY Loss_Ratio;

SELECT Loss_Ratio, AVG(Nearest_Firestation_miles) AS avg_station_distance_miles
FROM fire_claim
GROUP BY Loss_Ratio;

SELECT AVG(Loss_Ratio) AS average_loss_ratio
FROM fire_claim
WHERE Year_Built < 1980;

SELECT median(Loss_Ratio) AS median_loss_ratio
FROM fire_claim
WHERE Year_Built >= 2010;

SELECT AVG(Nearest_Firestation_miles) AS avg_distance_to_nearest_firestation
FROM fire_claim
WHERE Fireplace = 'Yes';

SELECT AVG(Number_of_Firefighters) AS avg_firefighters
FROM fire_claim
WHERE Fireplace = 'No';

SELECT MAX(Loss_Ratio) AS max_loss_ratio
FROM fire_claim
WHERE Nearest_Firestation_miles <= 3;

SELECT median(Nearest_Firestation_miles) AS median_station_distance
FROM fire_claim
WHERE Number_of_Firefighters < 6;

SELECT AVG(CASE WHEN LOWER(Fireplace) IN ('yes', 'y', 'true', '1') THEN 1.0 ELSE 0.0 END) AS fireplace_share
FROM fire_claim
WHERE Number_of_Firefighters >= 9;

SELECT SUM(Policy_Amount) AS total_annual_premium
FROM policy_amount
WHERE Amount_Type_Code = 'Annual Premium';

SELECT Claim_Identifier, SUM(Claim_Amount) AS total_claim_amount
FROM claim_amount
GROUP BY Claim_Identifier;

SELECT Postal_Code, COUNT(*) AS address_count
FROM location_address
GROUP BY Postal_Code;

SELECT ca.Claim_Identifier, ca.Claim_Amount_Identifier, ca.Claim_Amount
FROM claim_amount ca
JOIN expense_reserve er ON ca.Claim_Amount_Identifier = er.Claim_Amount_Identifier;
